out=[[0]*11 for _ in range(10)]
rows=["888........",
"...8.......",
"8...8......",
".8...8.....",
"..88888...."]
for i,s in enumerate(rows):
    for j,ch in enumerate(s):
        if ch=='8': out[2+i][j]=8
import math
H=len(inp);W=len(inp[0])
def rot(deg, shrink=1.0):
    o=[[0]*W for _ in range(H)]
    th=math.radians(deg)
    cy=(H-1)/2; cx=(W-1)/2
    for r in range(H):
        for c in range(W):
            if inp[r][c]:
                y=(r-cy)/shrink; x=(c-cx)/shrink
                nr=y*math.cos(th)-x*math.sin(th)+cy
                nc=y*math.sin(th)+x*math.cos(th)+cx
                ir,ic=round(nr),round(nc)
                if 0<=ir<H and 0<=ic<W: o[ir][ic]=8
    return o
for deg in [20,26.57,30,35,40,45,-20,-30,-45]:
    o=rot(deg)
    match=sum(1 for r in range(H) for c in range(W) if o[r][c]==out[r][c])
    print(deg, match, sum(map(sum,o)), sum(map(sum,out)))
    if match>=H*W-3:
        for r in o: print(''.join('8' if v else '.' for v in r))
